// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber1, uint256 blockNumber2) public {
        vm.assume(blockNumber1 > 0 && blockNumber2 > 0);
        vm.assume(blockNumber1 != blockNumber2);
        vm.assume(blockNumber1 <= 1000 && blockNumber2 <= 1000);

        address sender = address(0x1234);
        uint256 requiredValue = 10 ether;

        vm.deal(sender, requiredValue * 2);
        vm.roll(blockNumber1);
        vm.warp(blockNumber1);
        vm.prank(sender);
        (bool success1,) = address(c).call{value: requiredValue}("");
        require(success1, "First call failed unexpectedly");

        vm.roll(blockNumber2);
        vm.warp(blockNumber2);
        vm.prank(sender);
        (bool success2,) = address(c).call{value: requiredValue}("");

        assertTrue(!success2 || (blockNumber2 > blockNumber1));
    }
}
